const patch=(id:number,side:number,e:Element[],images:ImageRegion[]=[],background='#fff',notes:string[]=[])=>patches[`l${String(id).padStart(2,'0')}/s0${side}`]={background,clearShapes:true,removeText:[{x:0,y:0,w:1280,h:920}],elements:e,images,notes}
